test_wraps_signature[
# identifier:A
import functools
def f(x):
 pass
def x(f):
 @functools.wraps(f)
 def wrapper(*args):
 return f(*args)
 return wrapper

x(f)(-f(x, /)]

test_wraps_signature[
# identifier:B
import functools
def f(x):
 pass
def x(f):
 @functools.wraps(f)
 def wrapper():
 # Have no arguments here, but because of wraps, the signature
 # should still be f's.
 return 1
 return wrapper

x(f)(-f()]

test_wraps_signature[
# identifier:C
import functools
def f(x: int, y: float):
 pass

@functools.wraps(f)
def wrapper(*args, **kwargs):
 return f(*args, **kwargs)

wrapper(-f(x: int, y: float)]

test_wraps_signature[
# identifier:D
def f(x: int, y: float):
 pass

def wrapper(*args, **kwargs):
 return f(*args, **kwargs)

wrapper(-wrapper(x: int, y: float)]
